/* Phenomenon Atlas v2 — part 4: method and per-board help dialogs, event binding, boot. */
'use strict';
/* ---------- method (global) and help (per board) ---------- */
function openMethod() { const m = state.meta; $('#methodContent').innerHTML = `<p class="method-tour"><button type="button" class="text-btn" data-act="tour">New here? Take the tour of the site →</button></p><h3>01 / Scope</h3><p>The atlas starts from ${fmt(m.episodes_master)} podcast episodes that have a transcript and a matching YouTube video, from ${longDate(m.date_from)} to ${longDate(m.date_to)}. A language model read every transcript in full. It scored each episode from 0 to 100 for how relevant it is to business strategy, and it listed 3 to 8 problems that practitioners raise in it, each with a word-for-word quote. Episodes that scored below ${m.relevance_min} are left out, which leaves ${fmt(m.episodes)}. A problem is kept only when its quote is found word for word in the transcript. In all, ${fmt(m.problems)} problems passed this check.</p>`
  + `<h3>02 / Topics</h3><p>A text-embedding model (bge-m3) turned each problem into a list of numbers, so that problems with similar meaning get similar numbers. The problems were then grouped by similarity into ${fmt(m.topics)} topics, and a language model named each topic from its most typical problems. On the map every topic has a fixed place, computed so that topics with similar problems sit near each other (a t-SNE layout). The distance between two topics is only a layout, not a measurement. In the Map view each topic spreads colour around its place in proportion to how often it was discussed in podcasts in the period. The Squares view shows each research field as a row of squares, one per topic, from the least to the most discussed in podcasts.</p>`
  + `<h3>03 / Counts</h3><p>A topic's count for a period is the number of podcast episodes in that period that raise at least one of its problems. Audience points give each of those episodes 0 to 2 points by how its YouTube views rank among videos uploaded in the same week, so the median episode earns 1 point and a topic can have more points than episodes. Ranking within the week means an older video does not count more just because it has had longer to collect views. It also removes the effect of YouTube's change in how it counted views in August 2026. Only videos uploaded in 2026 earn points. Each episode falls in the month of its YouTube upload date. When that date is more than 60 days away from the podcast's own date, the podcast date is used instead and the episode earns no points.</p>`
  + `<h3>04 / Research fields</h3><p>Research fields are 17 fields of strategy research, taken from 30 years of keywords in six management journals, plus Others. A language model scored every problem on each of the 17 fields, reading the quote and the passage around it, and a problem counts for a field when it scores 50 or more. A topic belongs to a field when at least 10 of its problems count for the field, those problems make up at least 5% of the topic, and that share is at least twice the field's share among all problems. Topics with no such field go to Others.</p>`
  + `<h3>05 / Questions and papers</h3><p>Core questions are written by a language model from the quotes of at least two episodes from different shows. A second model checked each question part by part against those quotes, and near-duplicate questions within a topic were removed. Related papers come from an index of 10,470 papers: AMJ, AMR, ASQ, SMJ, OS and JOM in issues from 1996 to 2026, the strategy departments of Management Science from 2003, and papers added in 2026. A paper is dated by the journal issue it appears in, not by when it first went online. For each question, about 20 papers closest to it by embedding were retrieved, and a model scored every one of them from 0 to 100 for relevance. Papers that scored 60 or more were kept. Core papers scored ${CORE_REL} or more. The rest are loosely related.</p>`
  + `<h3>06 / Ask</h3><p>Ask has two parts. Search compares your text with every topic's description and core questions, and lists the closest topics. No AI writes anything there. The AI assistant uses your API key or Codex CLI to assess one question. The site computes how often podcasts raise it. Your selected model rates the closest papers, picks the most relevant quotes, notes each related paper and writes a short judgment. It sees only those quotes and papers.</p>`;
  const tb = $('#methodContent [data-act=tour]'); if (tb) tb.onclick = () => { $('#methodDialog').close(); window.atlasTour && atlasTour.start(); };   // tour.js
  $('#methodDialog').showModal(); }
// per-board help; functions of meta so that the numbers come from the data
const HELP = {
  map: m => ['How to read the map board', `<h3>Counts</h3><p><b>Episodes</b>: how many podcast episodes in the period raise at least one problem of the topic, each counted once. <b>Audience points</b>: each of those episodes earns 0 to 2 points by how its YouTube views rank among videos uploaded in the same week. The median episode earns 1 point, a widely watched one up to 2 and a barely watched one close to 0, so a topic whose episodes are watched more than usual has more points than episodes. Ranking within the week means an older video does not count more just because it has had longer to collect views, and it removes the effect of YouTube's change in how it counted views in August 2026. Under a research field, a topic counts only the episodes whose problems concern that field.</p>`
    + `<h3>Map</h3><p>Each topic has a fixed place on the map, and topics with similar problems sit close together. The distance between two topics is only a layout, not a measurement. Colour shows how much each part of the map was discussed in podcasts in the period you picked: red means many episodes, dark blue means few. The colours are relative to what is on screen, so they show where the podcast discussion is in that period, not whether one month was busier than another. The map is drawn again whenever you change the period, the count, the research field or the search. All names are the same size. Where two names would overlap, the more discussed topic keeps its name. Zoom in to see more names, and click a name to open the topic.</p>`
    + `<h3>Squares</h3><p>Each row is a research field with every topic that belongs to it, so a topic can appear in more than one row. Each square is one topic. Within a row the squares run from the topic least discussed in podcasts on the left to the most discussed on the right. The colour goes from blue for the least discussed, through light blue and light red, to red for the most discussed, in eight steps, by how the topic ranks among all the squares shown. The number under a row's name counts different episodes across its topics, so an episode that raises several of them counts once. The change on the period before is shown only when both periods are complete, so not for the last month or quarter, which the data do not fully cover, nor for the first, nor for the whole year. Others is always the last row. Hover a square for the topic, click it to open the topic, or click a row's name to show that row alone with larger squares.</p>`
    + `<h3>List</h3><p>All topics in the current selection, ranked by how often they were discussed in podcasts in the period. Click a topic to open it.</p>`
    + `<h3>Trend</h3><p>Use the three buttons to switch between sets of ranked cards, one line per card, so that each field or topic can be read on its own. Each card shows its latest value in large type and the change since the first month or year. Point at a line to read another month. <b>Episodes per research field</b>: distinct podcast episodes each month, using the same counts as Squares. Each episode counts once within a field. Only episodes whose problems concern that field count. An episode in several fields counts in each. <b>The 20 most discussed topics of 2026</b>: podcast episodes per month for the 20 topics with the most episodes from 1 January to 6 October 2026, or for the top 20 of the field you picked. Fields are ranked by their latest month or year, topics by their 2026 total, and a field you pick has a red rule. <b>Papers per research field</b>: journal papers in the index per year from 2006 to 2025, dated by the journal issue they appear in. A paper in several fields counts in each. The months run from January to September 2026, because the data end on 6 October. The cards in a set share one scale and their heights can be compared. Each set has a table with the numbers.</p>`],
  gap: m => ['How to read the gap board', `<h3>Podcast count</h3><p>As on the map: how many podcast episodes discussed the topic in the period, or their audience points, within the research field you picked.</p>`
    + `<h3>Paper count</h3><p>How many different papers are linked to the topic's core questions. Each question was matched to about 20 papers in the index by text similarity. A model then scored every one of them from 0 to 100 for relevance. <b>All related papers</b>, the default, counts every paper that scored 60 or more. <b>Core papers only</b> counts papers that scored ${CORE_REL} or more, which study the same question or mechanism. A paper linked to several questions of a topic counts once.</p>`
    + `<h3>Ranking the list</h3><p><b>Podcasts</b> puts the most discussed topics first and <b>Papers</b> the topics with the most papers. <b>Gap</b> compares a topic's place in the two rankings of the listed topics. Each place is a percentile from 0, the fewest, to 100, the most, and tied topics share the middle place. Gap is the podcast percentile minus the paper percentile, from −100 to 100. A topic ahead of 90% of topics in podcasts and of 20% in papers has a gap of 70. <b>Many podcasts, few papers</b> lists the largest positive gaps first, and <b>Many papers, few podcasts</b> the largest negative gaps first. The gap changes with the period, the count, the research field and the papers counted.</p>`
    + `<h3>Quadrant</h3><p>Each topic is placed by its rank on both counts within the group you picked, so the two lines cross at the middle topic on each count. Top right, many podcasts and many papers: discussed in podcasts and studied in papers. Bottom right, many podcasts and few papers: discussed a lot in podcasts but studied little in papers. Top left, few podcasts and many papers: well studied in papers but rarely discussed in podcasts now. Bottom left, few podcasts and few papers: little of either. Small dots show every topic in the group. The large circles are 12 topics picked at random in each quadrant (6 on a phone). Click a circle or a name to open the topic.</p>`],
  ask: m => ['How to read the ask board', `<h3>Search</h3><p>No AI is involved and no account is needed. A text-embedding model (bge-m3) turns your text into a list of numbers and compares it with every topic. A topic's score is the average of two similarities: to the topic's description, and to the topic's core question that comes closest to your text. Topics that score 0.55 or more are listed, best first, at most 10. When none reaches 0.55, the three closest are shown as weak matches. The order comes from text similarity only, so a topic further down can still be off the point. Open a topic for its core questions, podcast quotes and papers. <b>Read in context</b> shows the quote with up to 200 words before and after it (an excerpt, for copyright reasons) and links to the podcast and the YouTube video.</p>`
    + `<h3>AI assistant</h3><p>Connect your API key or an installed and signed-in Codex CLI. Your provider or CLI account limits apply. For the same connection, a question asked before gets its locally saved answer without a new model call. You type one question in English and get a fixed assessment. The numbers are computed by the site, and the model only judges and picks.</p>`
    + `<p><b>In podcasts.</b> The site counts the episodes that raise a problem closely related to your question (similarity 0.60 or more). None means not discussed in podcasts, and fewer than 10 means rarely discussed in podcasts. Otherwise the site takes the topic that holds most of these episodes and ranks it among the ${fmt(m.topics)} topics by its episodes in the year: below the middle means discussed in podcasts now and then, the upper half means often discussed in podcasts, and the top tenth means among the most discussed in podcasts.</p>`
    + `<p><b>In papers.</b> The model rates the 20 papers closest to your question from 0 to 100, as the atlas does for its own paper links. Papers rated 85 or more study the same question or mechanism. None means not studied in papers, one means studied a little in papers, two means studied in papers, and three or more means well studied in papers. Every paper rated 60 or more is listed, highest rated first. For comparison, of the atlas's 6,895 core questions 19% have no such paper. Only seven journals are indexed, so a question can be studied elsewhere.</p>`
    + `<p>The model also picks the three to five most relevant quotes, writes a short note on each listed paper and writes short judgments. It sees only those quotes and papers, and each judgment links to the items it uses.</p>`]};
function openHelp() { const h = (HELP[state.board] || HELP.map)(state.meta); $('#helpTitle').textContent = h[0]; $('#helpContent').innerHTML = h[1]; $('#helpDialog').showModal(); }

/* ---------- ask board: built by ask.js and auth.js (ASK v2, 2026-10-21); askStatus() is defined there ---------- */

/* ---------- events ---------- */
function bind() {
  bindDetailResize(); bindTopicPage();   // app3.js
  $$('.rail-btn').forEach(b => b.onclick = () => setBoard(b.dataset.board)); $('#logoBtn').onclick = () => setBoard('home');
  $('#themeSelect').onchange = e => { state.theme = e.target.value; updateScopeNote(); closeDetail(true); transitionMap(); renderList(); };
  $('#themeBtn').onclick = () => applyTheme(!isLight()); $('#helpBtn').onclick = openHelp; $('#closeHelp').onclick = () => $('#helpDialog').close();
  $$('.mode-switch button').forEach(b => b.onclick = () => { state.mode = b.dataset.mode; const list = periodsOfMode(); const cur = periodObj(); const match = list.find(p => cur && p.start.slice(0, 7) <= cur.start.slice(0, 7) && (list[list.indexOf(p) + 1] ? list[list.indexOf(p) + 1].start.slice(0, 7) > cur.start.slice(0, 7) : true)); choosePeriod((match || list[list.length - 1]).id); });
  $$('.heat-switch button').forEach(b => b.onclick = () => { state.heat = b.dataset.heat; renderTime(); transitionMap(); renderList(); renderRank(); if (state.selected) renderDetail(); });
  $('#periodSelect').onchange = e => choosePeriod(e.target.value); $('#prevPeriod').onclick = () => { const l = periodsOfMode(), i = l.findIndex(p => p.id === state.period); if (i > 0) choosePeriod(l[i - 1].id); }; $('#nextPeriod').onclick = () => { const l = periodsOfMode(), i = l.findIndex(p => p.id === state.period); if (i < l.length - 1) choosePeriod(l[i + 1].id); };
  const setView = v => { state.view = v; [['map', '#viewMap'], ['squares', '#viewSquares'], ['list', '#viewList'], ['trend', '#viewTrend']].forEach(([k, id]) => $(id).classList.toggle('selected', k === v));
    $('#mapCanvas').hidden = v !== 'map'; $('.map-bottom').hidden = v !== 'map'; $('#listPanel').hidden = v !== 'list'; $('#squaresPanel').hidden = v !== 'squares'; $('#trendPanel').hidden = v !== 'trend';
    $('#timeLens').hidden = v === 'trend'; $('.scope-search').hidden = v === 'trend';   // the charts span the year and show no search
    paintHowto(v === 'trend' ? 'trend' : 'map'); hideTip(); hideSqTip(); state.hover = null; if (v === 'list') renderList(); else if (v === 'trend') renderTrend(); else transitionMap(); };
  $('#viewMap').onclick = () => setView('map'); $('#viewSquares').onclick = () => setView('squares'); $('#viewList').onclick = () => setView('list'); $('#viewTrend').onclick = () => setView('trend');
  $('#search').oninput = e => { state.search = e.target.value; state.zoom = 1; state.tx = 0; state.ty = 0; renderMap(); renderList(); };
  $('#closeDetail').onclick = () => closeDetail(); $$('.detail-tabs button').forEach(b => b.onclick = () => { state.tab = b.dataset.tab; renderDetail(); });
  $('#methodBtn').onclick = openMethod; $('#closeMethod').onclick = () => $('#methodDialog').close();
  $('#rankAcad').onchange = e => { state.acad = e.target.value; renderRank(); }; $('#rankBy').onchange = e => { state.rankBy = e.target.value; renderRank(); };
  $('#rankTheme').onchange = e => { state.rankTheme = e.target.value; closeDetail(true); renderRank(); }; $$('.rank-tabs button').forEach(b => b.onclick = () => { state.rtab = b.dataset.rtab; renderRank(); });
  const mc = $('#mapCanvas');
  mc.addEventListener('wheel', e => { e.preventDefault(); const box = mc.getBoundingClientRect(); const mx = e.clientX - box.left - box.width / 2, my = e.clientY - box.top - box.height / 2; const f = e.deltaY < 0 ? 1.18 : 1 / 1.18; const z = Math.max(.7, Math.min(8, state.zoom * f)); const k = z / state.zoom; state.tx = mx - (mx - state.tx) * k; state.ty = my - (my - state.ty) * k; state.zoom = z; renderMap({quick: true}); settle(); $('#zoomReset').textContent = Math.round(z * 100) + '%'; }, {passive: false});
  const settle = () => { clearTimeout(state.settleT); state.settleT = setTimeout(() => renderMap(), 160); };
  mc.addEventListener('mousedown', e => { if (e.target.closest('.topic-label')) return; state.drag = {x: e.clientX, y: e.clientY, tx: state.tx, ty: state.ty, moved: false}; mc.classList.add('dragging'); });
  window.addEventListener('mousemove', e => {
    if (state.drag) { const dx = e.clientX - state.drag.x, dy = e.clientY - state.drag.y; if (Math.abs(dx) + Math.abs(dy) > 3) state.drag.moved = true; state.tx = state.drag.tx + dx; state.ty = state.drag.ty + dy; renderMap({quick: true}); settle(); } });
  window.addEventListener('mouseup', e => { if (!state.drag) return; const moved = state.drag.moved; state.drag = null; mc.classList.remove('dragging'); if (!moved && !e.target.closest('.topic-label') && e.target.closest('#mapCanvas')) { const t = nearestTopic(e); if (t) selectTopic(t.id); } });
  const zoomBy = f => { const z = Math.max(.7, Math.min(8, state.zoom * f)), k = z / state.zoom; animateCamera({zoom: z, tx: state.tx * k, ty: state.ty * k}, 320); };
  $('#zoomIn').onclick = () => zoomBy(1.3); $('#zoomOut').onclick = () => zoomBy(1 / 1.3); $('#zoomReset').onclick = () => flyHome();
  window.addEventListener('resize', () => { renderMap(); if (state.board === 'gap' && state.rtab === 'quad') renderRank(); });
}
load().then(openFromHash).catch(e => { $('#boardCopy').textContent = 'Failed to load data: ' + e; console.error(e); });
